const directions = (()=>{const a:{name:string;v:[number,number,number]}[]=[];for(let x=-1;x<=1;x++)for(let y=-1;y<=1;y++)for(let z=-1;z<=1;z++){if(!x&&!y&&!z)continue;const names=[x===1?'Справа':x===-1?'Слева':'',y===1?'Сверху':y===-1?'Снизу':'',z===1?'Спереди':z===-1?'Сзади':''].filter(Boolean);a.push({name:names.join(' · '),v:[x,y,z]})}return a})();
function Part({item,selected,onSelect,wire,section,sectionOffset,edges}:{item:Item;selected:boolean;onSelect:(e:ThreeEvent<MouseEvent>)=>void;wire:boolean;section:string;sectionOffset:number;edges:boolean}){if(!item.visible)return null;const normal=section==='XY'?new THREE.Vector3(0,0,-1):section==='XZ'?new THREE.Vector3(0,-1,0):new THREE.Vector3(-1,0,0);const planes=section==='off'?[]:[new THREE.Plane(normal,sectionOffset)];const common={color:selected?'#ffb347':item.color,metalness:.42,roughness:.35,wireframe:wire,clippingPlanes:planes,side:THREE.DoubleSide};const mesh=(geometry:React.ReactNode)=><mesh castShadow receiveShadow onClick={onSelect}>{geometry}<meshStandardMaterial {...common}/>{edges&&!wire&&<lineSegments><edgesGeometry args={[item.kind==='box'?new THREE.BoxGeometry(...item.size):new THREE.CylinderGeometry(item.size[0]/2,item.size[0]/2,item.size[1],32)]}/><lineBasicMaterial color={selected?'#ffdd82':'#243e55'} clippingPlanes={planes}/></lineSegments>}</mesh>;return <group position={item.pos} onClick={onSelect} userData={{modelGeometry:true}}>{item.kind==='box'?mesh(<boxGeometry args={item.size}/>):item.kind==='gear'?<group><mesh rotation={[Math.PI/2,0,0]}><cylinderGeometry args={[item.size[0],item.size[0],item.size[1],32]}/><meshStandardMaterial {...common}/></mesh>{Array.from({length:16},(_,i)=><mesh key={i} position={[Math.cos(i*Math.PI/8)*item.size[0],Math.sin(i*Math.PI/8)*item.size[0],0]} rotation={[0,0,i*Math.PI/8]}><boxGeometry args={[.16,.16,item.size[1]]}/><meshStandardMaterial {...common}/></mesh>)}</group>:<group rotation={[Math.PI/2,0,0]}>{mesh(<cylinderGeometry args={[item.size[0]/2,item.size[0]/2,item.size[1],32]}/>)}</group>}</group>}
